import { Handler } from '@zcatalyst/transport';
import { CONSTANTS, isValidInputString, wrapValidators, wrapValidatorsWithPromise } from '@zcatalyst/utils';
import pkg from '../package.json';
const { version } = pkg;
import { Segment } from './segment';
import { CatalystCacheError } from './utils/error';
const { REQ_METHOD, COMPONENT, CREDENTIAL_USER } = CONSTANTS;
export class Cache {
    constructor(app) {
        this.requester = new Handler(app, this);
    }
    getComponentName() {
        return COMPONENT.cache;
    }
    getComponentVersion() {
        return version;
    }
    async getAllSegment() {
        const request = {
            method: REQ_METHOD.get,
            path: `/segment`,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const resp = await this.requester.send(request);
        const json = resp.data;
        const segmentsArr = [];
        json.data.forEach((segment) => {
            segmentsArr.push(new Segment(this, segment));
        });
        return segmentsArr;
    }
    async getSegmentDetails(id) {
        await wrapValidatorsWithPromise(() => {
            isValidInputString(id, 'segment_id', true);
        }, CatalystCacheError);
        const request = {
            method: REQ_METHOD.get,
            path: `/segment/${id}`,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const resp = await this.requester.send(request);
        const json = resp.data;
        return new Segment(this, json.data);
    }
    segment(id) {
        if (typeof id === 'undefined') {
            return new Segment(this, {});
        }
        wrapValidators(() => {
            isValidInputString(id, 'segment_id', true);
        }, CatalystCacheError);
        return new Segment(this, { id });
    }
}
export * from './utils/interface';
